package main

const pageHTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>YourMove Realize</title><script>try{document.documentElement.dataset.theme=localStorage.getItem('theme')||''}catch(e){}</script><style>
:root{color-scheme:light;--bg:#F5F4F1;--surface:#fff;--ink:#242933;--muted:#606773;--line:#D9DDE3;--blue:#3459A5;--on:#fff;--wash:#eceef1}[data-theme=dark]{color-scheme:dark;--bg:#191C22;--surface:#22262E;--ink:#EDF0F5;--muted:#b8c0cc;--line:#424955;--blue:#AAC5FF;--on:#191C22;--wash:#2b3039}@media(prefers-color-scheme:dark){:root:not([data-theme=light]){color-scheme:dark;--bg:#191C22;--surface:#22262E;--ink:#EDF0F5;--muted:#b8c0cc;--line:#424955;--blue:#AAC5FF;--on:#191C22;--wash:#2b3039}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}header{max-width:1280px;margin:auto;padding:25px 40px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line)}.brand{font-weight:750;letter-spacing:-.04em}.brand span{font-weight:400;color:var(--muted);margin-left:6px}main{max-width:1200px;margin:auto;padding:65px 40px 110px}h1,h2,h3,p{margin:0 0 18px}h1{font:normal clamp(42px,5.6vw,72px)/1.08 Georgia,serif;letter-spacing:-.045em}h2{font-size:30px;line-height:1.2;letter-spacing:-.025em}h3{font-size:19px;line-height:1.3}.lede{font-size:19px;line-height:1.55;color:var(--muted)}.muted,small{color:var(--muted)}small{font-size:13px}.hero{display:grid;grid-template-columns:1fr 1fr;gap:10%;align-items:start;padding-top:35px}.hero h1{max-width:580px}.intro{max-width:500px}.intake{border-top:1px solid var(--ink)}.intake section{padding:24px 0;border-bottom:1px solid var(--line)}.intake h2{font-size:21px;margin-bottom:8px}.narrow{max-width:780px}.wide{max-width:1000px}.preview{white-space:pre-wrap;max-height:340px;overflow:auto;background:var(--surface);border:1px solid var(--line);padding:22px;font:14px/1.65 ui-monospace,monospace}.actions{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:24px 0}button,.button{display:inline-block;background:var(--blue);color:var(--on);border:1px solid var(--blue);padding:12px 20px;border-radius:2px;font:inherit;font-weight:650;cursor:pointer;text-decoration:none}button:hover,.button:hover{opacity:.85}.secondary{background:transparent;color:var(--ink);border-color:var(--line)}.link{background:none;border:0;color:var(--blue);padding:4px 0;text-decoration:underline}.theme{background:transparent;color:var(--ink);border-color:var(--line);font-size:13px;padding:6px 12px}:focus-visible{outline:3px solid var(--blue);outline-offset:3px}textarea,input[type=text]{display:block;width:100%;background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:2px;padding:14px;font:inherit}textarea{resize:vertical;min-height:130px}label{display:block;font-weight:650;margin:18px 0 8px}input[type=file]{max-width:100%;margin:10px 0}.notice{border-left:3px solid var(--blue);background:var(--surface);padding:16px 20px;margin-bottom:25px}.lead{display:block;width:100%;text-align:left;background:transparent;color:var(--ink);border:0;border-top:1px solid var(--line);border-radius:0;padding:22px 0;font-weight:400}.lead strong{display:block;font-size:19px}.lead span{color:var(--muted)}.lead:hover{color:var(--blue)}.conversation{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:8%;align-items:start}.context{border-left:1px solid var(--line);padding-left:25px}.context summary{color:var(--ink)}.context pre{font:14px/1.65 inherit;white-space:pre-wrap;max-height:60vh;overflow:auto;color:var(--muted)}.context pre{font-family:inherit}.history{margin:20px 0 30px;border-bottom:1px solid var(--line)}.history p{white-space:pre-wrap}.history .turn{border-top:1px solid var(--line);padding:16px 0 4px}.history small{display:block}.question{font-size:24px;line-height:1.4;letter-spacing:-.015em;margin:20px 0}.signal{border-left:3px solid var(--blue);padding:6px 0 6px 20px;margin:25px 0}.signal p{margin-bottom:10px}.insight{border-top:1px solid var(--ink);padding-top:28px;margin-top:30px}.insight h2{font:normal clamp(30px,4vw,46px)/1.15 Georgia,serif}.record{padding:28px 0;border-top:1px solid var(--line)}.record p{white-space:pre-wrap}.quote,blockquote{white-space:pre-wrap;border-left:2px solid var(--blue);margin:16px 0;padding:5px 0 5px 20px;color:var(--muted)}details{margin:18px 0}summary{cursor:pointer;color:var(--blue);font-weight:650}.waiting{display:none;color:var(--muted);margin-top:12px}.busy .waiting{display:block}.busy button[type=submit]{opacity:.6;pointer-events:none}.source-list{display:grid;grid-template-columns:1fr 1fr;gap:25px}.source-list blockquote{margin:5px 0}.print-only{display:none}footer{max-width:1200px;margin:auto;border-top:1px solid var(--line);padding:24px 40px;color:var(--muted);font-size:13px}@media(max-width:700px){header{padding:20px}main{padding:40px 20px 70px}.hero,.conversation,.source-list{grid-template-columns:1fr;gap:30px}.hero{padding-top:0}.conversation .context{grid-row:1;border:0;border-bottom:1px solid var(--line);padding:0 0 15px}.context pre{max-height:240px}.actions>*{max-width:100%}h1{font-size:43px}footer{padding:20px}}@media(min-width:701px){.context details>div{display:block}.context summary{margin-bottom:10px}}@media print{header,footer,.no-print,button{display:none!important}main{padding:0;max-width:none}body{background:white;color:#222}.record,.insight{break-inside:avoid}.print-only{display:block}details:not([open])>div{display:block}summary{color:#222}}
</style></head><body><header><div class="brand">YourMove <span>/ Realize</span></div><button class="theme no-print" id="theme" type="button">◐ &nbsp; Theme</button></header><main>
{{if .Notice}}<div class="notice" role="alert">{{.Notice}}</div>{{end}}
{{if eq .Stage "welcome"}}<div class="hero"><section class="intro"><h1>There’s more to your story.</h1><p class="lede">Rediscover the decisions, knowledge, and strengths hidden in the work you’ve already done.</p><p class="muted">Bring a résumé or a piece of your experience. We’ll explore it together, one question at a time.</p></section><div class="intake"><section><h2>Upload a résumé</h2><p class="muted">A PDF or Word document, up to 10 MiB.</p><form action="/upload" method="post" enctype="multipart/form-data"><label for="file">Choose a file</label><input id="file" name="resume" type="file" accept=".pdf,.docx" required><div><button type="submit">Upload and preview</button></div></form></section><section><h2>Paste career text</h2><p class="muted">A role, project, skills section, single bullet, or an informal account of your work.</p><form action="/paste" method="post"><label for="career_text">Your experience</label><textarea id="career_text" name="career_text" rows="7" required placeholder="Paste or describe something you’ve worked on…"></textarea><div class="actions"><button type="submit">Preview text</button></div></form></section></div></div>
{{else if eq .Stage "preview"}}<div class="narrow"><h2>Take a look before we begin.</h2>{{if eq .InputKind "paste"}}<p class="lede">This is the text you supplied.</p>{{else}}<p class="lede">This text was extracted locally from {{.Filename}}.</p>{{end}}{{if .Truncated}}<div class="notice">Only the first 8,000 bytes shown here will be sent and considered. The rest has not been analyzed.</div>{{end}}<div class="preview">{{.State.Resume.Text}}</div><p style="margin-top:24px">When you begin, this text and your subsequent answers are sent to Baseten for AI inference. Your account is not independently verified. Session data is held in memory while the server runs.</p><form action="/begin" method="post" class="infer"><div class="actions">{{if eq .InputKind "paste"}}<button type="submit" name="approach" value="focused">Explore this experience →</button><button class="secondary" type="submit" name="approach" value="leads">Choose a starting point</button>{{else}}<button type="submit">Begin discovery →</button>{{end}}</div><p class="waiting" role="status">Requesting a starting point from Baseten…</p></form><form action="/reset" method="post"><button class="link">Start over</button></form></div>
{{else if eq .Stage "leads"}}<div class="narrow"><h2>Where would you like to begin?</h2><p class="lede">Choose a promising thread. These are suggestions based on your material, and you can return to another.</p>{{range .State.Leads}}<form action="/select" method="post" class="infer"><button class="lead" name="lead" value="{{.ID}}"><strong>{{.Title}} →</strong><span>{{.Why}}</span></button><p class="waiting" role="status">Requesting a question from Baseten…</p></form>{{end}}{{if .Discoveries}}<form action="/collection" method="post"><button class="link">Return to discoveries</button></form>{{end}}</div>
{{else if eq .Stage "conversation"}}<div class="conversation"><section><p class="muted">{{if .State.SelectedLead}}Exploring {{.State.SelectedLead.Title}}{{else}}Exploring your experience{{end}}</p>{{if .State.Responses}}<details class="history"><summary>Conversation so far ({{len .State.Responses}})</summary><div>{{range .State.Responses}}<div class="turn"><small>Realize asked</small><p>{{.Question}}</p><small>You said</small><p>{{.Source.Text}}</p></div>{{end}}</div></details>{{end}}{{if .State.Proposal}}<div class="signal"><h3>There’s something here to consider.</h3><p>{{.State.Proposal.Title}}</p><form method="post" action="/reveal"><button class="link">See the discovery →</button></form></div>{{end}}{{if .State.Question}}{{if lt (len .State.Responses) 6}}<p class="question">{{.State.Question}}</p><form action="/answer" method="post" class="infer"><label for="answer">Your response</label><textarea id="answer" name="answer" maxlength="2000" required placeholder="What happened? You can also correct anything I misunderstood."></textarea><div class="actions"><button type="submit">Continue →</button></div><p class="waiting" role="status">Sending your answer to Baseten for the next question…</p></form>{{else}}<p class="notice">This conversation has reached its six-response limit. {{if not .State.Proposal}}There isn’t enough supported detail for a discovery yet.{{end}}</p>{{end}}{{else}}<p>Your recorded answers are still here.</p><form action="/retry" method="post" class="infer"><button>Retry the request</button><p class="waiting" role="status">Requesting a question from Baseten…</p></form>{{end}}{{if .Discoveries}}<form action="/collection" method="post"><button class="link">Return to discoveries</button></form>{{end}}</section><aside class="context"><details id="context"><summary>Your original material</summary><div><pre>{{.State.Resume.Text}}</pre>{{if .Truncated}}<small>Only this excerpt was analyzed.</small>{{end}}</div></details></aside></div>
{{else if eq .Stage "reveal"}}<div class="narrow"><p class="muted">A possible discovery · your account, interpreted</p><div class="insight"><h2>{{.State.Proposal.Title}}</h2><h3>What you did</h3><p>{{.State.Proposal.Experience}}</p><h3>What this may reveal</h3><p>{{.State.Proposal.Claim}}</p><h3>What remains open</h3>{{if .State.Proposal.Unresolved}}<ul>{{range .State.Proposal.Unresolved}}<li>{{.}}</li>{{end}}</ul>{{else}}<p class="muted">The model identified no specific unknowns; check for anything missing.</p>{{end}}<details><summary>Inspect the supporting statement</summary><div><blockquote>{{.State.Proposal.Quote}}</blockquote><small>{{.State.Proposal.SourceID}} · an exact quotation from your account. A quotation does not by itself prove the interpretation.</small></div></details><div class="actions"><form action="/review" method="post"><button>Does this describe your contribution? →</button></form><form action="/continue" method="post"><button class="secondary">Keep talking</button></form></div></div></div>
{{else if eq .Stage "review"}}<div class="narrow"><h2>Does this accurately describe your contribution?</h2><p class="lede">Check the interpretation against every statement below and correct it before keeping it. The cited passage may not support every detail. Your review is not independent verification.</p><form method="post" action="/keep"><label for="title">Title</label><input id="title" name="title" maxlength="160" value="{{.State.Proposal.Title}}" required><label for="experience">What you did</label><textarea id="experience" name="experience" maxlength="1500" required>{{.State.Proposal.Experience}}</textarea><label for="claim">What this suggests</label><textarea id="claim" name="claim" maxlength="1500" required>{{.State.Proposal.Claim}}</textarea><h3 style="margin-top:24px">What remains open</h3>{{if .State.Proposal.Unresolved}}<ul>{{range .State.Proposal.Unresolved}}<li>{{.}}</li>{{end}}</ul>{{else}}<p class="muted">None identified by the model.</p>{{end}}<details open><summary>Recorded conversation and cited statement</summary><div>{{range .State.Responses}}<blockquote>{{.Source.Text}}</blockquote><small>{{.Source.ID}}{{if eq .Source.ID $.State.Proposal.SourceID}} · cited source{{end}}</small>{{end}}<p><small>Exact cited passage: “{{.State.Proposal.Quote}}”. Edits do not change the original statements.</small></p></div></details><div class="actions"><button>Keep this discovery</button></div></form><form method="post" action="/reject"><button class="link">Discard suggestion and continue talking</button></form></div>
{{else if eq .Stage "saved"}}<div class="wide"><h2>Your discoveries</h2><p class="lede">These are your reviewed interpretations, grounded in the experiences you described.</p>{{range .Discoveries}}<article class="record"><h3>{{.Title}}</h3><p>{{.Experience}}</p><p>{{.Claim}}</p><details><summary>Sources and open questions</summary><div>{{range .Responses}}<blockquote>{{.Source.Text}}</blockquote><small>{{.Source.ID}}</small>{{end}}{{if .Unresolved}}<p>Still open:</p><ul>{{range .Unresolved}}<li>{{.}}</li>{{end}}</ul>{{end}}</div></details><form action="/edit" method="post"><button class="link" name="id" value="{{.ID}}">Review or correct wording</button></form></article>{{end}}<div class="actions">{{if lt (len .Discoveries) 4}}<form action="/explore" method="post" class="infer"><label for="focus">What else would you like to explore? <small>(optional)</small></label><input id="focus" name="focus" maxlength="120" placeholder="Another responsibility or experience"><button>Explore another experience</button><p class="waiting" role="status">Requesting a question from Baseten…</p></form>{{end}}{{if ge (len .Discoveries) 2}}<form action="/connections" method="post" class="infer"><button class="secondary">Find connections →</button><p class="waiting" role="status">Asking Baseten to examine the reviewed experiences…</p></form>{{end}}<form action="/takeaway" method="post"><button class="secondary">View your takeaway</button></form></div><p class="muted">Saved in this session only. Reviewed by you, not independently verified.</p></div>
{{else if eq .Stage "connections"}}<div class="wide"><p class="muted">Across your experiences</p><h1>Look at what connects.</h1><p class="lede">These are interpretations of recurring actions, not verified facts. Consider whether they ring true.</p>{{if .Synthesis.Connections}}{{range .Synthesis.Connections}}<article class="insight"><h2>{{.Capability}}</h2><p class="lede">{{.Interpretation}}</p><p>{{.Relationship}}</p><div class="source-list">{{range .Supports}}<div><small>Discovery {{.EvidenceID}} · your contribution</small><p>{{.Action}}</p><blockquote>“{{.Quote}}”</blockquote></div>{{end}}</div><h3>What this does not establish</h3><ul>{{range .Limitations}}<li>{{.}}</li>{{end}}</ul><h3>Language you might use</h3><p class="quote">{{.CandidateUse}}</p>{{if .FollowUp}}<p class="muted">A question to consider: {{.FollowUp}}</p>{{end}}<p><small>You can challenge this interpretation by returning to a discovery and correcting its wording. Connections will then need to be generated again.</small></p></article>{{end}}{{else}}<div class="insight"><h2>No defensible connection emerged yet.</h2><p>The experiences may need more detail, or they may simply describe different kinds of work. Neither diminishes what you did.</p></div>{{end}}<form action="/challenge" method="post"><label for="challenge">Does this interpretation miss something?</label><textarea id="challenge" name="challenge" maxlength="2000" placeholder="Add your perspective or challenge the connection.">{{.Challenge}}</textarea><button class="secondary">Record my perspective</button><p><small>Your challenge is kept separately from the interpretation and is not automatically approved as evidence.</small></p></form><div class="actions"><form action="/collection" method="post"><button class="secondary">Back to discoveries</button></form><form action="/takeaway" method="post"><button>View your takeaway →</button></form></div></div>
{{else if eq .Stage "takeaway"}}<div class="wide"><p class="muted">YourMove Realize · a personal reflection</p><h1>What your experience reveals.</h1><p class="lede">A record of your own account and reviewed interpretations. These are not independently verified facts.</p>{{range .Discoveries}}<article class="record"><h2>{{.Title}}</h2><h3>Your contribution</h3><p>{{.Experience}}</p><h3>What it may show</h3><p>{{.Claim}}</p>{{if .Unresolved}}<h3>Still open</h3><ul>{{range .Unresolved}}<li>{{.}}</li>{{end}}</ul>{{end}}<details><summary>Supporting statements</summary><div>{{range .Responses}}<blockquote>{{.Source.Text}}</blockquote>{{end}}</div></details></article>{{end}}{{if .Synthesis}}{{range .Synthesis.Connections}}<article class="insight"><h2>{{.Capability}}</h2><p>{{.Interpretation}}</p><p>{{.Relationship}}</p><h3>Words to consider</h3><p class="quote">{{.CandidateUse}}</p><h3>Limits</h3><ul>{{range .Limitations}}<li>{{.}}</li>{{end}}</ul></article>{{end}}{{end}}{{if .Challenge}}<h3>Your perspective on the connection</h3><p>{{.Challenge}}</p>{{end}}<div class="actions no-print"><button type="button" onclick="window.print()">Print or save as PDF</button><a class="button secondary" href="/download">Download JSON</a><form action="/collection" method="post"><button class="secondary">Back to discoveries</button></form></div></div>{{end}}
</main><footer>YourMove Realize · Your experience belongs to you.</footer><script>let context=document.getElementById('context');if(context&&matchMedia('(min-width: 701px)').matches)context.open=true;document.getElementById('theme').addEventListener('click',()=>{let d=document.documentElement,c=d.dataset.theme||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');d.dataset.theme=c==='dark'?'light':'dark';try{localStorage.setItem('theme',d.dataset.theme)}catch(e){}});document.querySelectorAll('form.infer').forEach(f=>f.addEventListener('submit',()=>f.classList.add('busy')));</script></body></html>`
